def transform(grid):
    """
    Identifies header rows and extracts unique marker values.
    Output shape: 1xN with unique markers from header rows.
    """
    from collections import Counter

    counts = Counter()
    for row in grid:
        for val in row:
            counts[val] += 1

    # Separator is second most frequent, fill is most frequent
    items = sorted(counts.items(), key=lambda x: -x[1])
    F = items[0][0]  # Fill
    S = items[1][0] if len(items) > 1 else F  # Separator

    # Find unique markers (values not equal to S or F)
    markers = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] not in (S, F):
                markers.add(grid[r][c])

    # Collect in order of first appearance
    marker_list = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            val = grid[r][c]
            if val not in (S, F) and val not in marker_list:
                marker_list.append(val)

    return [[x for x in marker_list]]
